"""CLI app generated by intpot."""
from __future__ import annotations


from pathlib import Path

import asyncio as _intpot_cli_asyncio
import inspect as _intpot_cli_inspect

import typer as _intpot_cli_typer

STOCK_UNITS = 150

UNIT_PRICE = 12

def reservation_cost(quantity: int, packs: int) -> int:
    if quantity * packs > STOCK_UNITS:
        raise ValueError('reservation exceeds available stock')
    return quantity * packs * UNIT_PRICE

app = _intpot_cli_typer.Typer(name='inventory', help='inventory — powered by intpot')
_intpot_required = object()


def _reserve_inventory_impl(
    quantity: int = _intpot_required,
    packs: int = 1,
    receipt: str = '',
) -> dict:
    """Reserve a bounded number of inventory units without mutable server state."""
    if quantity is _intpot_required:
        raise TypeError('Missing required argument: quantity')
    cost = reservation_cost(quantity, packs)
    result = {'quantity': quantity, 'packs': packs, 'cost': cost}
    if receipt:
        Path(receipt).write_text(str(result), encoding='utf-8')
    return result


@app.command(name='reserve_inventory')
def reserve_inventory(
    quantity: int = _intpot_cli_typer.Argument(..., help='', min=1, max=100),
    packs: int = _intpot_cli_typer.Option(1, help='', min=1, max=5),
    receipt: str = _intpot_cli_typer.Option('', help=''),
) -> None:
    """Reserve a bounded number of inventory units without mutable server state."""
    result = _reserve_inventory_impl(quantity, packs, receipt)
    if _intpot_cli_inspect.iscoroutine(result):
        result = _intpot_cli_asyncio.run(result)
    if result is not None:
        _intpot_cli_typer.echo(result)


if __name__ == "__main__":
    app()
